import { mkdir, readFile, writeFile } from 'node:fs/promises';

const shapes = new URL('../shapes/', import.meta.url);
const catalog = JSON.parse(await readFile(new URL('shapes.json', shapes), 'utf8'));
const assets = {};
for (const id of Object.keys(catalog).sort()) {
  assets[id] = await readFile(new URL(catalog[id].file, shapes), 'utf8');
}
const output = new URL('../src/generated/symbol-assets.ts', import.meta.url);
await mkdir(new URL('.', output), { recursive: true });
await writeFile(output,
  '// Generated by scripts/build-shape-assets.mjs. Edit the source SVGs through their approved workflow.\n'
  + `export const symbolAssets: Readonly<Record<string, string>> = ${JSON.stringify(assets, null, 2)};\n`,
  'utf8');
